agent_runs.agent_sql:
SELECT ?partyType (COUNT(?p) AS ?count) WHERE {
  ?p a <http://curated-layer-ontology-20260804-065536/ontology/vkg-ontology_curated_layer-ed486e6f/Party> ;
     <http://curated-layer-ontology-20260804-065536/ontology/vkg-ontology_curated_layer-ed486e6f/Party/party_type> ?partyType .
}
GROUP BY ?partyType
ORDER BY DESC(?count)
LIMIT 5

SELECT ?riderName ?fullName ?participantSk
WHERE {
  ?rider a <http://curated-layer-ontology-20260804-065536/ontology/vkg-ontology_curated_layer-ed486e6f/Rider> ;
         <http://curated-layer-ontology-20260804-065536/ontology/vkg-ontology_curated_layer-ed486e6f/Rider/rider_name> ?riderName ;
         <http://curated-layer-ontology-20260804-065536/ontology/vkg-ontology_curated_layer-ed486e6f/Rider/holding_id> ?holdingId ;
         <http://curated-layer-ontology-20260804-065536/ontology/vkg-ontology_curated_layer-ed486e6f/Rider/is_deleted> ?riderDeleted .
  FILTER(LCASE(STR(?riderDeleted)) = "false")

  ?rp a <http://curated-layer-ontology-20260804-065536/ontology/vkg-ontology_curated_layer-ed486e6f/RiderParticipant> ;
      <http://curated-layer-ontology-20260804-065536/ontology/vkg-ontology_curated_layer-ed486e6f/RiderParticipant/holding_id> ?holdingId ;
      <http://curated-layer-ontology-20260804-065536/ontology/vkg-ontology_curated_layer-ed486e6f/RiderParticipant/participant_sk> ?participantSk ;
      <http://curated-layer-ontology-20260804-065536/ontology/vkg-ontology_curated_layer-ed486e6f/RiderParticipant/is_deleted> ?rpDeleted .
  FILTER(LCASE(STR(?rpDeleted)) = "false")

  ?coverage a <http://curated-layer-ontology-20260804-065536/ontology/vkg-ontology_curated_layer-ed486e6f/Coverage> ;
            <http://curated-layer-ontology-20260804-065536/ontology/vkg-ontology_curated_layer-ed486e6f/Coverage/holding_id> ?holdingId ;
            <http://curated-layer-ontology-20260804-065536/ontology/vkg-ontology_curated_layer-ed486e6f/Coverage/party_id> ?partyIdRaw .

  ?party a <http://curated-layer-ontology-20260804-065536/ontology/vkg-ontology_curated_layer-ed486e6f/Party> ;
         <http://curated-layer-ontology-20260804-065536/ontology/vkg-ontology_curated_layer-ed486e6f/Party/party_id> ?partyId ;
         <http://curated-layer-ontology-20260804-065536/ontology/vkg-ontology_curated_layer-ed486e6f/Party/full_name> ?fullName .

  BIND(CONCAT("PARTY#", ?partyIdRaw) AS ?partyIdPrefixed)
  FILTER(?partyIdPrefixed = ?partyId)
}
ORDER BY ?riderName ?fullName

SELECT ?full_name (SUM(?mv) AS ?totalMarketValue)
WHERE {
  ?h a <http://curated-layer-ontology-20260804-065536/ontology/vkg-ontology_curated_layer-ed486e6f/Holding> ;
     <http://curated-layer-ontology-20260804-065536/ontology/vkg-ontology_curated_layer-ed486e6f/Holding/holding_status> "Active" ;
     <http://curated-layer-ontology-20260804-065536/ontology/vkg-ontology_curated_layer-ed486e6f/Holding/holding_id> ?holdingId ;
     <http://curated-layer-ontology-20260804-065536/ontology/vkg-ontology_curated_layer-ed486e6f/Holding/market_value> ?mv .

  ?c a <http://curated-layer-ontology-20260804-065536/ontology/vkg-ontology_curated_layer-ed486e6f/Coverage> ;
     <http://curated-layer-ontology-20260804-065536/ontology/vkg-ontology_curated_layer-ed486e6f/Coverage/holding_id> ?holdingId ;
     <http://curated-layer-ontology-20260804-065536/ontology/vkg-ontology_curated_layer-ed486e6f/Coverage/party_id> ?covPartyId .

  ?p a <http://curated-layer-ontology-20260804-065536/ontology/vkg-ontology_curated_layer-ed486e6f/Party> ;
     <http://curated-layer-ontology-20260804-065536/ontology/vkg-ontology_curated_layer-ed486e6f/Party/party_id> ?partyId ;
     <http://curated-layer-ontology-20260804-065536/ontology/vkg-ontology_curated_layer-ed486e6f/Party/full_name> ?full_name .

  BIND(CONCAT("PARTY#", ?covPartyId) AS ?prefixedPartyId)
  FILTER(?prefixedPartyId = ?partyId)
}
GROUP BY ?full_name
ORDER BY DESC(?totalMarketValue)

SELECT ?full_name ?premium_mode (SUM(?amount) AS ?projected_next_payout_amount)
WHERE {
  ?ad a <http://curated-layer-ontology-20260804-065536/ontology/vkg-ontology_curated_layer-ed486e6f/AnnuityDetail> ;
      <http://curated-layer-ontology-20260804-065536/ontology/vkg-ontology_curated_layer-ed486e6f/AnnuityDetail/holdingId> ?holdingId ;
      <http://curated-layer-ontology-20260804-065536/ontology/vkg-ontology_curated_layer-ed486e6f/AnnuityDetail/deleted> ?adDeleted .
  FILTER(LCASE(STR(?adDeleted)) = "false")

  ?cov a <http://curated-layer-ontology-20260804-065536/ontology/vkg-ontology_curated_layer-ed486e6f/Coverage> ;
       <http://curated-layer-ontology-20260804-065536/ontology/vkg-ontology_curated_layer-ed486e6f/Coverage/holding_id> ?holdingId ;
       <http://curated-layer-ontology-20260804-065536/ontology/vkg-ontology_curated_layer-ed486e6f/Coverage/party_id> ?partyKey ;
       <http://curated-layer-ontology-20260804-065536/ontology/vkg-ontology_curated_layer-ed486e6f/Coverage/product_code> ?productCode ;
       <http://curated-layer-ontology-20260804-065536/ontology/vkg-ontology_curated_layer-ed486e6f/Coverage/is_deleted> ?covDeleted .
  FILTER(LCASE(STR(?covDeleted)) = "false")

  BIND(CONCAT("PARTY#", ?partyKey) AS ?partyId)

  ?party a <http://curated-layer-ontology-20260804-065536/ontology/vkg-ontology_curated_layer-ed486e6f/Party> ;
         <http://curated-layer-ontology-20260804-065536/ontology/vkg-ontology_curated_layer-ed486e6f/Party/party_id> ?partyId ;
         <http://curated-layer-ontology-20260804-065536/ontology/vkg-ontology_curated_layer-ed486e6f/Party/full_name> ?full_name .

  ?pp a <http://curated-layer-ontology-20260804-065536/ontology/vkg-ontology_curated_layer-ed486e6f/PolicyProduct> ;
      <http://curated-layer-ontology-20260804-065536/ontology/vkg-ontology_curated_layer-ed486e6f/PolicyProduct/product_code> ?productCode ;
      <http://curated-layer-ontology-20260804-065536/ontology/vkg-ontology_curated_layer-ed486e6f/PolicyProduct/premium_mode> ?premium_mode .

  ?fa a <http://curated-layer-ontology-20260804-065536/ontology/vkg-ontology_curated_layer-ed486e6f/FinancialActivity> ;
      <http://curated-layer-ontology-20260804-065536/ontology/vkg-ontology_curated_layer-ed486e6f/FinancialActivity/holding_id> ?holdingId ;
      <http://curated-layer-ontology-20260804-065536/ontology/vkg-ontology_curated_layer-ed486e6f/FinancialActivity/activity_type> ?activityType ;
      <http://curated-layer-ontology-20260804-065536/ontology/vkg-ontology_curated_layer-ed486e6f/FinancialActivity/transaction_amount> ?amount ;
      <http://curated-layer-ontology-20260804-065536/ontology/vkg-ontology_curated_layer-ed486e6f/FinancialActivity/is_deleted> ?faDeleted .
  FILTER(?activityType IN ("Withdrawal","Dividend","Claim"))
  FILTER(LCASE(STR(?faDeleted)) = "false")
}
GROUP BY ?full_name ?premium_mode
ORDER BY ?full_name

SELECT DISTINCT ?product_name
WHERE {
  ?cp a <http://curated-layer-ontology-20260804-065536/ontology/vkg-ontology_curated_layer-ed486e6f/CoverageProduct> ;
      <http://curated-layer-ontology-20260804-065536/ontology/vkg-ontology_curated_layer-ed486e6f/CoverageProduct/product_name> ?product_name .
}
ORDER BY ?product_name
LIMIT 10

SELECT ?month (SUM(?amount) AS ?totalAmount)
WHERE {
  ?fa a <http://curated-layer-ontology-20260804-065536/ontology/vkg-ontology_curated_layer-ed486e6f/FinancialActivity> ;
      <http://curated-layer-ontology-20260804-065536/ontology/vkg-ontology_curated_layer-ed486e6f/FinancialActivity/transaction_date> ?date ;
      <http://curated-layer-ontology-20260804-065536/ontology/vkg-ontology_curated_layer-ed486e6f/FinancialActivity/transaction_amount> ?amount ;
      <http://curated-layer-ontology-20260804-065536/ontology/vkg-ontology_curated_layer-ed486e6f/FinancialActivity/is_deleted> ?deleted .
  FILTER(LCASE(STR(?deleted)) = "false")
  FILTER(STRSTARTS(STR(?date), "2024"))
  BIND(SUBSTR(STR(?date),1,7) AS ?month)
}
GROUP BY ?month
ORDER BY ?month

SELECT ?party ?partyName (SUM(?mv) AS ?totalMarketValue) (GROUP_CONCAT(DISTINCT ?fundname; separator=", ") AS ?investmentProducts)
WHERE {
  ?party a <http://curated-layer-ontology-20260804-065536/ontology/vkg-ontology_curated_layer-ed486e6f/Party> ;
         <http://curated-layer-ontology-20260804-065536/ontology/vkg-ontology_curated_layer-ed486e6f/Party/full_name> ?partyName .

  ?coverage a <http://curated-layer-ontology-20260804-065536/ontology/vkg-ontology_curated_layer-ed486e6f/Coverage> ;
            <http://curated-layer-ontology-20260804-065536/ontology/vkg-ontology_curated_layer-ed486e6f/Coverage/hasParty> ?party ;
            <http://curated-layer-ontology-20260804-065536/ontology/vkg-ontology_curated_layer-ed486e6f/Coverage/hasHolding> ?holding .

  ?holding a <http://curated-layer-ontology-20260804-065536/ontology/vkg-ontology_curated_layer-ed486e6f/Holding> ;
           <http://curated-layer-ontology-20260804-065536/ontology/vkg-ontology_curated_layer-ed486e6f/Holding/market_value> ?mv .

  OPTIONAL {
    ?sub a <http://curated-layer-ontology-20260804-065536/ontology/vkg-ontology_curated_layer-ed486e6f/HoldingSubaccount> ;
         <http://curated-layer-ontology-20260804-065536/ontology/vkg-ontology_curated_layer-ed486e6f/HoldingSubaccount/hasHolding> ?holding ;
         <http://curated-layer-ontology-20260804-065536/ontology/vkg-ontology_curated_layer-ed486e6f/HoldingSubaccount/fundname> ?fundname .
  }
}
GROUP BY ?party ?partyName
ORDER BY DESC(?totalMarketValue)
LIMIT 10
